// Parse Claude response and extract JSON
const items = [];

for (const item of $input.all()) {
  try {
    const response = item.json;
    let textContent = '';

    // Extract text from Claude response
    if (response.content && Array.isArray(response.content) && response.content.length > 0) {
      textContent = response.content[0].text || '';
    } else if (typeof response === 'string') {
      textContent = response;
    }

    // Clean markdown code blocks if any
    textContent = textContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // Extract first valid JSON object
    const jsonMatch = textContent.match(/\{[\s\S]*\}/);
    if (!jsonMatch) {
      throw new Error('No JSON object found in response');
    }

    const parsed = JSON.parse(jsonMatch[0]);

    // Add original email metadata
    const originalEmail = $('Normalize Email').item.json;
    parsed.original_from = originalEmail.from;
    parsed.original_subject = originalEmail.subject;
    parsed.original_messageId = originalEmail.messageId;
    parsed.original_date = originalEmail.date;
    parsed.original_body = originalEmail.body;

    // Generate thread_key if missing
    if (!parsed.thread_key || parsed.thread_key === '') {
      parsed.thread_key = (parsed.original_from + '_' + parsed.original_subject)
        .replace(/[^a-zA-Z0-9_-]/g, '_')
        .substring(0, 50);
    }

    // Ensure lead.email is set
    if (parsed.lead && !parsed.lead.email) {
      parsed.lead.email = parsed.original_from;
    }

    items.push({ json: parsed });

  } catch (error) {
    // Fallback: create minimal valid structure
    const originalEmail = $('Normalize Email').item.json;
    items.push({
      json: {
        lead: {
          email: originalEmail.from,
          nom: '',
          prenom: '',
          telephone: '',
          entreprise: '',
          service_demande: '',
          description_projet: originalEmail.body.substring(0, 200),
          budget_montant: null,
          budget_devise: 'CHF',
          delai_souhaite: ''
        },
        intent: 'autre',
        language: 'fr',
        can_quote_now: false,
        completeness_score: 0.2,
        missing_fields: ['nom', 'service_demande', 'budget'],
        questions: [],
        thread_key: (originalEmail.from + '_error').replace(/[^a-zA-Z0-9_-]/g, '_'),
        reply_draft: '<p>Merci pour votre message. Nous reviendrons vers vous rapidement.</p>',
        original_from: originalEmail.from,
        original_subject: originalEmail.subject,
        original_messageId: originalEmail.messageId,
        parse_error: error.message
      }
    });
  }
}

return items;

// Calculate detailed quote based on pricing rules
const items = [];

for (const item of $input.all()) {
  const lead = item.json.lead || {};
  const service = (lead.service_demande || '').toLowerCase();
  const description = (lead.description_projet || '').toLowerCase();
  const budget = lead.budget_montant || 0;

  // Pricing grid (editable)
  const pricing = {
    site_vitrine: {
      base: 2500,
      per_page: 300,
      cms: 800,
      seo_base: 500,
      forms: 400
    },
    ecommerce: {
      base: 5000,
      per_product_category: 500,
      payment: 800,
      shipping: 600
    },
    seo: {
      audit: 800,
      onpage_monthly: 600,
      content_monthly: 400,
      backlinks_monthly: 800
    },
    agent_ia: {
      email_automation: 1500,
      crm_integration: 1200,
      chatbot: 2000,
      custom_workflow: 2500
    }
  };

  const lines = [];

  // Detect service and build quote lines
  if (service.includes('site') || service.includes('web') || description.includes('site')) {
    const pages = parseInt(description.match(/(\d+)\s*page/i)?.[1] || '5');
    const basePrice = pricing.site_vitrine.base + (pages * pricing.site_vitrine.per_page);

    lines.push({
      description: `Site vitrine (${pages} pages)`,
      quantity: 1,
      unit_price: basePrice,
      total: basePrice
    });

    if (description.includes('cms') || description.includes('wordpress')) {
      lines.push({
        description: 'CMS / Administration',
        quantity: 1,
        unit_price: pricing.site_vitrine.cms,
        total: pricing.site_vitrine.cms
      });
    }

    if (description.includes('seo')) {
      lines.push({
        description: 'SEO de base',
        quantity: 1,
        unit_price: pricing.site_vitrine.seo_base,
        total: pricing.site_vitrine.seo_base
      });
    }

    if (description.includes('formulaire') || description.includes('contact')) {
      lines.push({
        description: 'Formulaires personnalisés',
        quantity: 1,
        unit_price: pricing.site_vitrine.forms,
        total: pricing.site_vitrine.forms
      });
    }
  }

  if (service.includes('seo') && !service.includes('site')) {
    lines.push({
      description: 'Audit SEO complet',
      quantity: 1,
      unit_price: pricing.seo.audit,
      total: pricing.seo.audit
    });
  }

  if (service.includes('agent') || service.includes('ia') || service.includes('automation')) {
    if (description.includes('email')) {
      lines.push({
        description: 'Agent IA Email',
        quantity: 1,
        unit_price: pricing.agent_ia.email_automation,
        total: pricing.agent_ia.email_automation
      });
    } else {
      lines.push({
        description: 'Workflow automation personnalisé',
        quantity: 1,
        unit_price: pricing.agent_ia.custom_workflow,
        total: pricing.agent_ia.custom_workflow
      });
    }
  }

  // Fallback
  if (lines.length === 0) {
    lines.push({
      description: 'Projet sur mesure',
      quantity: 1,
      unit_price: Math.max(budget * 0.8, 2000),
      total: Math.max(budget * 0.8, 2000)
    });
  }

  // Calculate totals
  const subtotal = lines.reduce((sum, line) => sum + line.total, 0);
  const tva_rate = 0.077;
  const tva_amount = subtotal * tva_rate;
  const total_ttc = subtotal + tva_amount;
  const estimated_weeks = Math.ceil(subtotal / 800);

  const quote = {
    quote_number: `LXS-${Date.now().toString().slice(-8)}`,
    date: new Date().toISOString().split('T')[0],
    client: {
      nom: lead.nom || '',
      prenom: lead.prenom || '',
      entreprise: lead.entreprise || '',
      email: lead.email,
      telephone: lead.telephone || ''
    },
    lines: lines,
    subtotal_ht: subtotal.toFixed(2),
    tva_rate: (tva_rate * 100).toFixed(1),
    tva_amount: tva_amount.toFixed(2),
    total_ttc: total_ttc.toFixed(2),
    devise: lead.budget_devise || 'CHF',
    delai_souhaite: lead.delai_souhaite || 'À définir',
    delai_estime: `${estimated_weeks} semaines`,
    validite: '30 jours',
    description_projet: lead.description_projet || ''
  };

  items.push({
    json: {
      ...item.json,
      quote: quote
    }
  });
}

return items;

